/* @autogenerated */
package net.civeira.phylax.features.oauth.consent.application;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.features.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.features.oauth.consent.domain.gateway.ScopesConsentGateway;

class ScopesConsentUsecaseUnitTest {

  private ScopesConsentGateway gateway = Mockito.mock(ScopesConsentGateway.class);
  private ScopesConsentUsecase usecase;

  @BeforeEach
  void setUp() {
    Mockito.reset(gateway);
    usecase = new ScopesConsentUsecase(gateway);
  }

  @Test
  @DisplayName("pendingScopes with null scope delegates empty list to gateway")
  void test_pending_scopes_null_scope() {
    Mockito.when(gateway.pendingScopes("t1", "user", "client", List.of())).thenReturn(List.of());
    List<ScopePermission> result = usecase.pendingScopes("t1", "user", "client", null);
    Assertions.assertTrue(result.isEmpty());
    Mockito.verify(gateway).pendingScopes("t1", "user", "client", List.of());
  }

  @Test
  @DisplayName("pendingScopes with blank scope delegates empty list to gateway")
  void test_pending_scopes_blank_scope() {
    Mockito.when(gateway.pendingScopes("t1", "user", "client", List.of())).thenReturn(List.of());
    List<ScopePermission> result = usecase.pendingScopes("t1", "user", "client", "   ");
    Assertions.assertTrue(result.isEmpty());
    Mockito.verify(gateway).pendingScopes("t1", "user", "client", List.of());
  }

  @Test
  @DisplayName("pendingScopes normalizes and deduplicates space-separated scopes")
  void test_pending_scopes_normalization() {
    List<String> normalized = List.of("openid", "profile", "email");
    ScopePermission perm = ScopePermission.builder().scope("openid").required(true).build();
    Mockito.when(gateway.pendingScopes("t1", "user", "client", normalized))
        .thenReturn(List.of(perm));

    List<ScopePermission> result =
        usecase.pendingScopes("t1", "user", "client", "openid  profile openid email");

    Assertions.assertEquals(1, result.size());
    Assertions.assertEquals("openid", result.get(0).getScope());
    Mockito.verify(gateway).pendingScopes("t1", "user", "client", normalized);
  }

  @Test
  @DisplayName("storeAcceptedScopes delegates normalized scopes to gateway")
  void test_store_accepted_scopes() {
    usecase.storeAcceptedScopes("t1", "user", "client", "openid profile");
    Mockito.verify(gateway).storeAcceptedScopes("t1", "user", "client",
        List.of("openid", "profile"));
  }

  @Test
  @DisplayName("storeAcceptedScopes with null scope delegates empty list")
  void test_store_accepted_scopes_null() {
    usecase.storeAcceptedScopes("t1", "user", "client", null);
    Mockito.verify(gateway).storeAcceptedScopes("t1", "user", "client", List.of());
  }
}
